INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (1, 24001, 24, 0, 10040, 1, "2020/04/30 12:00:00", 0, "リン", "あたしだって\nやるときはやるよ！", "2030/12/17 14:59:59", 0, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (1, 24002, 24, 0, 10040, 1, "2020/04/30 12:00:00", 0, "リン", "ふぅ…\nこれであたしの仕事は\n終わりだね", "2030/12/17 14:59:59", 1, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (1, 24003, 24, 0, 10040, 1, "2020/04/30 12:00:00", 0, "リン", "終わった終わった\n一人でもなんとか\nなるもんだね", "2030/12/17 14:59:59", 2, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (2, 24004, 24, 0, 10040, 2, "2020/04/30 12:00:00", 0, "リン", "やったね！\nこれでようやく\nサボれるよ…", "2030/12/17 14:59:59", 3, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (1, 24005, 24, 0, 10040, 1, "2020/04/30 12:00:00", 0, "リン", "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", "2030/12/17 14:59:59", 4, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (2, 24006, 24, 0, 10040, 2, "2020/04/30 12:00:00", 0, "リン", "あたしを敵に回した\n恐ろしさ\n思い知ったか！", "2030/12/17 14:59:59", 5, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (2, 24007, 24, 0, 10040, 2, "2020/04/30 12:00:00", 0, "リン", "あたしも意外と\nやるもんでしょ？", "2030/12/17 14:59:59", 6, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 24008, 24, 0, 10040, 4, "2020/04/30 12:00:00", 0, "リン", "疲れた…\nねずみの逃げ足\n速すぎるよ…", "2030/12/17 14:59:59", 7, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 24009, 24, 0, 10040, 4, "2020/04/30 12:00:00", 0, "リン", "このままじゃ\nまっひ～に\n叱られちゃうよ", "2030/12/17 14:59:59", 8, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 24010, 24, 0, 10040, 4, "2020/04/30 12:00:00", 0, "リン", "まじめに\nやったんだけどな…\n悔しいな～", "2030/12/17 14:59:59", 9, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 24011, 24, 0, 10040, 4, "2020/04/30 12:00:00", 0, "リン", "やられた…\nねずみって意外と\nてごわいね", "2030/12/17 14:59:59", 10, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 24012, 24, 0, 10040, 4, "2020/04/30 12:00:00", 0, "リン", "おのれ～\nあたしのチーズを\n盗みやがって～！", "2030/12/17 14:59:59", 11, 102601, 0);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 24013, 24, 0, 10040, 1, "2020/04/30 12:00:00", 0, "リン", "疲れた…\nけど、次こそは\n守り抜くよ…", "2030/12/17 14:59:59", 12, 102601, 1.81);
